-- =====================================================
-- KOORA V1 — Migration Teams (création + seed + logos)
-- =====================================================
-- Migration autonome et idempotente : crée la table teams,
-- insère 131 équipes et pose les logos vérifiés.
-- Réexécutable sans erreur (on conflict do update).
--
-- Logos : repo GitHub luukhopman/football-logos (URLs testées HTTP 200).
--   → 80 équipes européennes ont un logo.
--   → Les autres (Amérique, Afrique, Asie) ont logo_url = NULL :
--     le composant TeamLogo affiche les initiales en fallback.

-- 1. Table
create table if not exists public.teams (
    id uuid primary key default gen_random_uuid(),
    name text not null unique,
    logo_url text,
    country text,
    league text,
    created_at timestamptz default now()
);

-- 2. Index (autocomplete + filtre par pays)
create index if not exists idx_teams_name on public.teams(name);
create index if not exists idx_teams_country on public.teams(country);

-- 3. Seed + logos (idempotent : met à jour si l'équipe existe déjà)
on conflict (name) do update
  set logo_url = excluded.logo_url,
      country  = excluded.country,
      league   = excluded.league;

-- 4. Vérifications
select count(*) as total_teams from public.teams;
select count(*) as teams_with_logo from public.teams where logo_url is not null;
select name, country, league from public.teams where logo_url is null order by country, name;